style.css:
@-moz-document domain("roblox.com") {
/* Changer la couleur de fond de la page */
  body {
      background-color: #1E1E1E !important; /* Fond sombre */
      background-image: url('https://64.media.tumblr.com/580cf7c399ce7458dfb31fae5df78b46/b49af11512c9b8a3-70/s640x960/f54b4201912b615c311a002ae5b6d15908c1c545.gif') !important; /* Ajouter l'image GIF en fond */
      background-size: cover !important; /* L'image couvre toute la page */
      background-position: center !important; /* Centrer l'image */
      color: #FFFFFF !important; /* Texte en blanc */
      background-attachment: fixed !important; /* Fixe l'image en arrière-plan */
  }

  /* Personnaliser les bannières et éléments du haut */
  #header {
      background-color: rgba(34, 34, 34, 0.8) !important; /* Fond semi-transparent pour l'entête */
      color: #F1F1F1 !important; /* Texte clair pour l'entête */
  }

  /* Personnaliser les boutons */
  button, .button {
      background-color: #FF4B4B !important; /* Couleur rouge pour les boutons */
      color: white !important;
      border-radius: 5px;
  }

  /* Personnaliser les liens */
  a {
      color: #5D9BF5 !important; /* Lien bleu */
  }

  a:hover {
      color: #FF4B4B !important; /* Lien rouge au survol */
  }

  /* Modifier les avatars */
  .avatar-image {
      border: 3px solid #FF4B4B !important; /* Bordure rouge autour des avatars */
  }

  /* Personnaliser les pages de jeux */
  .game-card, .game-card-title {
      background-color: #2A2A2A !important; /* Fond sombre pour les cartes de jeu */
      color: #FFFFFF !important;
  }

  /* Personnaliser les menus déroulants */
  .menu {
      background-color: #333333 !important;
      color: #FFFFFF !important;
  }

  /* Style des notifications et alertes */
  .notification {
      background-color: #FF4B4B !important;
      color: white !important;
  }
}
